"""
Exhaustive verification of the rigidity gap on small grids.

For every subset R of an n x m grid (n, m <= 3) that is NOT a combinatorial box,
we compute the true optimum sup |A(f,g)|^2 over product coins -- which equals the
squared largest singular value of the 0/1 matrix of R -- and check the two
certified bounds

    sup |A|^2 <= 3|R|^2 / (3|R| + 1)        (multiplicative form)
    sup |A|^2 <= |R| - 2/7                  (additive form),

as well as the achievability bound max_a |R_a| <= sup |A|^2.  We also report the
smallest deficiency |R| - sup|A|^2 observed, which for every grid tested is the
golden value (3 - sqrt 5)/2 = 0.381966..., attained by the L-shape.

Self-contained: standard library only.
"""

from __future__ import annotations

from math import sqrt
from typing import Dict, List, Set, Tuple

Pair = Tuple[int, int]


def is_box(R: Set[Pair]) -> bool:
    P1 = {a for (a, _b) in R}
    P2 = {b for (_a, b) in R}
    return len(P1) * len(P2) == len(R) and all((a, b) in R for a in P1 for b in P2)


def sigma1(R: Set[Pair], n: int, m: int, sweeps: int = 600) -> float:
    """Top singular value of the 0/1 matrix of R, by alternating maximisation."""
    M = [[1.0 if (a, b) in R else 0.0 for b in range(m)] for a in range(n)]
    f = [1.0 / sqrt(n)] * n
    g = [1.0 / sqrt(m)] * m
    for _ in range(sweeps):
        Mg = [sum(M[a][b] * g[b] for b in range(m)) for a in range(n)]
        nf = sqrt(sum(t * t for t in Mg))
        if nf < 1e-300:
            return 0.0
        f = [t / nf for t in Mg]
        Mtf = [sum(M[a][b] * f[a] for a in range(n)) for b in range(m)]
        ng = sqrt(sum(t * t for t in Mtf))
        if ng < 1e-300:
            return 0.0
        g = [t / ng for t in Mtf]
    return sum(f[a] * M[a][b] * g[b] for a in range(n) for b in range(m))


def max_row(R: Set[Pair]) -> int:
    counts: Dict[int, int] = {}
    for (a, _b) in R:
        counts[a] = counts.get(a, 0) + 1
    return max(counts.values(), default=0)


def scan(n: int, m: int) -> None:
    cells: List[Pair] = [(a, b) for a in range(n) for b in range(m)]
    tested = boxes = violations = 0
    worst = float("inf")
    worst_set: Set[Pair] = set()
    for mask in range(1, 1 << len(cells)):
        R = {cells[i] for i in range(len(cells)) if mask >> i & 1}
        if is_box(R):
            boxes += 1
            continue
        tested += 1
        k = len(R)
        opt = sigma1(R, n, m) ** 2
        mult = 3.0 * k * k / (3.0 * k + 1.0)
        add = k - 2.0 / 7.0
        if opt > mult + 1e-8 or opt > add + 1e-8 or opt < max_row(R) - 1e-8:
            violations += 1
        if k - opt < worst:
            worst, worst_set = k - opt, R
    print(f"grid {n} x {m}: {tested} non-box sets, {boxes} boxes, {violations} violations")
    print(f"   smallest deficiency {worst:.9f} at R = {sorted(worst_set)}")
    print(f"   golden value (3 - sqrt 5)/2 = {(3 - sqrt(5)) / 2:.9f},  2/7 = {2/7:.9f}")


def main() -> None:
    for n, m in ((2, 2), (2, 3), (3, 3)):
        scan(n, m)


if __name__ == "__main__":
    main()

